#!/usr/bin/env bash\nset -euo pipefail\n\n# If an argument is provided, treat it as a file containing df output.\nif [[ $# -gt 0 ]]; then\n  DF_INPUT=\"$1\"\n  if [[ ! -f \"$DF_INPUT\" ]]; then\n    echo \"File not found: $DF_INPUT\" >&2\n    exit 1\n  fi\n  DF_DATA=$(cat \"$DF_INPUT\")\nelse\n  # Use df -h with a stable column layout, excluding tmpfs and devtmpfs for readability.\n  DF_DATA=$(df -h --output=source,size,used,avail,pcent,target -x tmpfs -x devtmpfs)\nfi\n\n# Process each line, skipping the header.\nwhile IFS= read -r line; do\n  [[ -z \"$line\" ]] && continue\n  if [[ \"$line\" == *\"Filesystem\"* ]]; then\n    continue\n  fi\n  # Extract fields using awk.\n  source=$(echo \"$line\" | awk '{print $1}')\n  pcent=$(echo \"$line\" | awk '{print $5}')\n  mount=$(echo \"$line\" | awk '{print $6}')\n  percent=${pcent%\%}\n  # Bar length: 20 characters total.\n  bar_len=$(( (percent * 20) / 100 ))\n  bar=$(printf \"%0.s#\" $(seq 1 $bar_len))\n  empty=$(printf \"%0.s-\" $(seq 1 $((20 - bar_len))))\n  printf \"%-20s %3s%% [%s%s]\n\" \"$mount\" \"$percent\" \"$bar\" \"$empty\"\n done <<< \"$DF_DATA\"\n
